mapper.select:
select kd.id, kd.question, kd.answer, c.name as categoryName, CASE uc.status WHEN 0 THEN '待审核' WHEN 1 THEN '已通过' END as statusDesc, kd.created_time, kd.reviewed_time from knowledge_draft kd left join category c on kd.category_id = c.id
and uc.status = #{query.status}
and kd.question like concat('%', #{query.keyword}, '%')
and kd.created_time >= #{query.startTime}
and kd.created_time <= #{query.endTime}
order by kd.created_time
desc
asc

select count(*)
from knowledge_draft
where status = #{status}
